INSERT INTO `normativas_documentos` (`titulo`, `tipo`, `resolucion_numero`, `organismo`, `url_oficial`, `archivo_pdf`, `descripcion`, `subido_por`) VALUES
('Diseño Curricular de la Provincia de Córdoba - Educación Secundaria', 'diseno_curricular', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://curriculumcordoba.ar/downloads/DISENO%20CURRICULAR-EDUCACION%20SECUNDARIA.pdf', 'oficial-diseno-curricular-secundaria.pdf', 'Vigente. Año 2025. Reúne Marco Curricular Común, Orientaciones Pedagógicas y Didácticas y Progresiones. Incluye la estructura curricular del nivel.', 1),
('Diseño Curricular, Tomo 11: Orientación Agro y Ambiente (2012-2015)', 'diseno_curricular', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://www.igualdadycalidadcba.gov.ar/SIPEC-CBA/publicaciones/EducacionSecundaria/LISTO%20PDF/ORIENTACION%20AGRO%20Y%20AMBIENTE.pdf', 'oficial-tomo11-agro-y-ambiente.pdf', 'Vigente. Año 2012. Plan de estudios y contenidos del Ciclo Orientado. Sigue siendo la base de la formación específica de Agro y Ambiente.', 1),
('Diseño Curricular, Tomo 2: Ciclo Básico (2011-2015)', 'diseno_curricular', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://www.igualdadycalidadcba.gov.ar/SIPEC-CBA/publicaciones/EducacionSecundaria/LISTO%20PDF/TOMO%202%20Ciclo%20Basico%20de%20la%20Educacion%20Secundaria%20web%208-2-11.pdf', 'oficial-tomo2-ciclo-basico.pdf', 'Histórico. Año 2011. Mapa curricular y carga horaria de 1.º a 3.º año. En 2026 se implementa el nuevo diseño del Ciclo Básico.', 1),
('Marco Curricular Común', 'diseno_curricular', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://curriculumcordoba.ar/downloads/MARCO%20CURRICULAR%20COMUN.pdf', 'oficial-marco-curricular-comun.pdf', 'Vigente. Año 2025. Fundamentos y capacidades fundamentales del currículum de Córdoba.', 1),
('Aprendizajes y Contenidos Fundamentales - Educación Secundaria', 'diseno_curricular', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://www.igualdadycalidadcba.gov.ar/SIPEC-CBA/publicaciones/DyPCurriculares/EduObligatoria/ApryContFund-sec-21082018.pdf', 'oficial-contenidos-fundamentales-2018.pdf', 'Histórico. Año 2018. Priorización de contenidos 2018. Las Progresiones de Aprendizaje cumplen hoy esa función.', 1),
('Actualización Curricular 2023: Formación para la Vida y el Trabajo', 'diseno_curricular', NULL, 'Ministerio de Educación de la Provincia de Córdoba', NULL, 'oficial-actualizacion-2023-fvt.pdf', 'Histórico. Año 2023. Documento de actualización curricular.', 1),
('Metas por ciclo', 'progresion', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://curriculumcordoba.ar/downloads/METAS%20POR%20CICLO.pdf', 'oficial-metas-por-ciclo.pdf', 'En consulta. Año 2025. Lo que se espera que cada estudiante logre al finalizar cada ciclo.', 1),
('Progresiones de Aprendizaje: Matemática', 'progresion', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://curriculumcordoba.ar/downloads/PROGRESIONES%20DE%20APRENDIZAJE%20DE%20MATEMATICA.pdf', 'oficial-pda-matematica.pdf', 'En consulta. Año 2025.', 1),
('Progresiones de Aprendizaje: Lenguaje - Lengua y Literatura', 'progresion', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://curriculumcordoba.ar/downloads/PROGRESIONES%20DE%20APRENDIZAJE%20DE%20LENGUAJE-LENGUA%20Y%20LITERATURA.pdf', 'oficial-pda-lengua.pdf', 'En consulta. Año 2025.', 1),
('Progresiones de Aprendizaje: Ciencias Naturales', 'progresion', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://curriculumcordoba.ar/downloads/PROGRESIONES%20DE%20APRENDIZAJE%20DE%20CS%20NATURALES.pdf', 'oficial-pda-ciencias-naturales.pdf', 'En consulta. Año 2025. Biología, Física y Química.', 1),
('Progresiones de Aprendizaje: Ciencias Sociales', 'progresion', NULL, 'Ministerio de Educación de la Provincia de Córdoba', 'https://curriculumcordoba.ar/downloads/PROGRESIONES%20DE%20APRENDIZAJE%20DE%20CS%20SOCIALES.pdf', 'oficial-pda-ciencias-sociales.pdf', 'En consulta. Año 2025. Geografía e Historia.', 1),
